 public static function defaults(): array {return ['revision'=>0,'timezone'=>'Asia/Tehran','weekend'=>[5],'holidays'=>[],'work_start'=>'08:00','cutoff'=>'16:00','transit_days'=>2,'grace_minutes'=>60,'province_days'=>[],'city_days'=>[],'blackout_dates'=>[],'capacity'=>100,'warning_hours'=>12,'max_open'=>10,'required_close_note'=>true,'effort_minutes'=>120,'weekly_shifts'=>[],'breaks'=>[['12:00','13:00']],'date_shifts'=>[]];}
 public static function validate(array $v): array {
  $p=array_replace(self::defaults(),array_intersect_key($v,self::defaults()));
