  if(!is_array($p['weekend'])||count($p['weekend'])>6)throw new \InvalidArgumentException('حداقل یک روز کاری لازم است.');
  foreach($p['weekend'] as $day)if(!is_int($day)||$day<0||$day>6)throw new \InvalidArgumentException('روز هفته نامعتبر است.');$p['weekend']=array_values(array_unique($p['weekend']));
