  foreach(['transit_days'=>30,'grace_minutes'=>1440,'capacity'=>10000,'warning_hours'=>168,'max_open'=>50] as $k=>$max){if(!is_numeric($p[$k])||(int)$p[$k]!=(float)$p[$k]||(int)$p[$k]<($k==='capacity'||$k==='max_open'?1:0)||(int)$p[$k]>$max)throw new \InvalidArgumentException('عدد سیاست خارج از محدوده است.');$p[$k]=(int)$p[$k];}
