  if(!is_numeric($p['effort_minutes'])||(int)$p['effort_minutes']!=(float)$p['effort_minutes']||$p['effort_minutes']<0||$p['effort_minutes']>14400)throw new \InvalidArgumentException('حداکثر ۱۴۴۰۰ دقیقه آماده‌سازی مجاز است.');$p['effort_minutes']=(int)$p['effort_minutes'];
