  $s=array_replace(['incidents'=>[],'history'=>[],'hold'=>false,'promise'=>[]],$s);$id=(string)($v['id']??'');$note=trim((string)($v['note']??''));if(strlen($note)>2000)throw new \InvalidArgumentException('یادداشت بیش از حد مجاز است.');
