 public static function page(): void {
  if(!Support::can('operations'))wp_die('دسترسی مجاز نیست.');$p=self::policy();$id=absint($_GET['order_id']??0);echo '<div class="wrap hmx-service" dir="rtl"><h1>تقویم تعهد محلی و پرونده استثنا</h1><p>برآورد برنامه داخلی فروشگاه است؛ وضعیت یا تعهد شرکت حمل نیست. تاریخ تعطیلی میلادی است.</p>';Support::notice();
  if(Support::can('settings')){echo '<details><summary>تنظیم تقویم و قواعد مسیر</summary>';Support::form('hm_mahex_v34_policy');echo '<input type="hidden" name="command" value="settings"><input type="hidden" name="revision" value="'.esc_attr($p['revision']).'">';echo '<input type="hidden" name="return_order_id" value="'.esc_attr($id).'">';self::settingsFields($p);echo '<button class="button button-primary">ذخیره سیاست</button></form></details>';}
  Support::orderChooser('hm-mahex-service-policies',$id);$o=$id?wc_get_order($id):null;if($o&&Support::can('operations',$id)){$s=$o->get_meta(self::META,true);$s=is_array($s)?$s:[];$preview=self::deadline($o->get_date_created()->date(DATE_ATOM),$p,$o->get_shipping_state(),$o->get_shipping_city());echo '<section><h2>برآورد سفارش #'.esc_html($id).'</h2><p>مهلت: '.esc_html($preview['deadline']).' | مسیر: '.esc_html(['default'=>'پیش‌فرض','province'=>'استان','city'=>'شهر'][$preview['route_source']]).' | ریسک: '.esc_html(['normal'=>'عادی','warning'=>'نزدیک مهلت','overdue'=>'گذشته از مهلت'][self::risk($s['promise']??$preview,time(),$p)]).'</p><p>روزهای حذف‌شده: '.esc_html(implode('، ',$preview['skipped_dates'])).' | دلایل: '.esc_html(implode('، ',$preview['reasons'])).'</p><p>وضعیت داخلی: '.esc_html(!empty($s['hold'])?'متوقف':'فعال').'</p>';self::form($id,$s,'promise','ثبت نسخه ثابت تعهد');self::form($id,$s,'forecast','برآورد جدید مستقل');self::form($id,$s,'override','اصلاح مهلت با دلیل',false,true,'','deadline');echo '<p>پذیرش مؤثر: '.esc_html($preview['accepted_at']).'</p>';echo '<p>آماده‌سازی: '.esc_html($preview['preparation']['minutes']).' دقیقه | تکمیل: '.esc_html($preview['preparation']['completed']).'</p>';echo '<details><summary>صورت ریز آماده‌سازی روزانه</summary><ul>';foreach($preview['preparation']['daily_minutes'] as $day=>$minutes)echo '<li>'.esc_html($day.' — '.$minutes.' دقیقه').'</li>';echo '</ul></details>';if(!empty($s['promise']['policy_hash'])&&$s['promise']['policy_hash']!==$preview['policy_hash'])echo '<p class="notice notice-warning">سیاست از زمان ثبت تعهد تغییر کرده است.</p>';echo '<p>مهلت اصلی: '.esc_html($s['original_deadline']??'').' | توقف انباشته: '.esc_html($s['pause_seconds']??0).' ثانیه</p>';if(!empty($s['forecast']))echo '<p>برآورد جدید: '.esc_html($s['forecast']['deadline']).'</p>';echo '<details><summary>نسخه‌های تعهد</summary><pre>'.esc_html(wp_json_encode($s['promise_history']??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></details>';echo '<p><a class="button" href="'.esc_url(wp_nonce_url(add_query_arg(['action'=>'hm_mahex_v34_case_export','order_id'=>$id],admin_url('admin-post.php')),'hm_mahex_v34_case_export')).'">خروجی خصوصی پرونده JSON</a></p>'; $summary=self::summary($s,time());$currency=$o->get_currency();echo '<p>باز: '.esc_html($summary['open']).' | بحرانی: '.esc_html($summary['critical']).' | معوق: '.esc_html($summary['overdue']).'</p>';if(Support::can('finance',$id))echo '<p>زیان: '.esc_html($summary['loss']).' | بازیافت: '.esc_html($summary['recovery']).' | خالص: '.esc_html($summary['net']).' | واحد پول سفارش: '.esc_html($currency).'</p>';echo '<input type="search" class="hmx-case-search" placeholder="جست‌وجوی پرونده">';echo '</section><section><h2>ثبت استثنا</h2>';self::form($id,$s,'open','ثبت پرونده',true);echo '</section><section><h2>توقف یا ادامه</h2>';self::form($id,$s,empty($s['hold'])?'hold':'resume',empty($s['hold'])?'توقف با دلیل':'ادامه با دلیل',false,true);echo '</section>';
   foreach($s['incidents']??[] as $incidentId=>$x){echo '<section class="hmx-incident" data-severity="'.esc_attr($x['severity']).'"><h3>'.esc_html(self::types()[$x['type']].' — '.(['open'=>'باز','acknowledged'=>'در رسیدگی','closed'=>'بسته'][$x['status']])).'</h3><p>'.esc_html($x['note']).'</p><p>مسئول: '.esc_html($x['owner']).' | مهلت: '.esc_html(gmdate('c',$x['due_at'])).' | سن: '.esc_html(max(0,(int)((time()-$x['created_at'])/3600))).' ساعت</p>';if($x['status']==='open')self::form($id,$s,'ack','پذیرش رسیدگی',false,false,$incidentId);self::form($id,$s,$x['status']==='closed'?'reopen':'resolve',$x['status']==='closed'?'بازگشایی':'بستن پرونده',false,true,$incidentId);self::form($id,$s,'assign','تغییر مسئول',false,false,$incidentId,'owner');self::form($id,$s,'due','تغییر مهلت رسیدگی',false,false,$incidentId,'due_at');if(Support::can('finance',$id)){echo '<p>هزینه ثبت‌شده: '.esc_html($x['cost']).' | واحد پول: '.esc_html($currency).'</p>';self::form($id,$s,'cost','ثبت هزینه استثنا ('.$currency.')',false,false,$incidentId,'cost');}foreach(['root_cause'=>'علت ریشه‌ای','corrective'=>'اقدام اصلاحی','preventive'=>'اقدام پیشگیرانه','contact'=>'نتیجه تماس','resolution'=>'طبقه نتیجه'] as $key=>$title){echo '<p>'.esc_html($title.': '.($x[$key]??'')).'</p>';self::form($id,$s,$key,$title,false,true,$incidentId);}echo '<p>زمان پذیرش: '.esc_html($x['ack_at']?max(0,$x['ack_at']-$x['created_at']):0).' ثانیه | زمان حل: '.esc_html($x['resolved_at']?max(0,$x['resolved_at']-$x['created_at']):0).' ثانیه | '.esc_html($x['status']!=='closed'&&$x['due_at']<time()?'مهلت گذشته':'در مهلت').'</p>';if(Support::can('finance',$id))self::form($id,$s,'recovery','مبلغ بازیافت ('.$currency.')',false,false,$incidentId,'recovery');echo '</section>';}
   echo '<details><summary>سوابق تغییرات</summary><ol>';foreach(array_reverse($s['history']??[]) as $h)echo '<li>'.esc_html(gmdate('c',$h['at']).' '.$h['command'].' '.$h['actor'].' '.$h['note']).'</li>';echo '</ol></details>';
  }
  echo '</div>';
 }
 private static function settingsFields(array $p): void {
  foreach(['effort_minutes'=>'آماده‌سازی (دقیقه)','transit_days'=>'حمل محلی (روز کاری)','grace_minutes'=>'فرجه (دقیقه)','warning_hours'=>'هشدار (ساعت)','max_open'=>'سقف پرونده باز'] as $key=>$label)echo '<label>'.esc_html($label).' <input type="number" min="0" name="'.esc_attr($key).'" value="'.esc_attr($p[$key]).'"></label>';
  foreach(['timezone'=>'منطقه زمانی','work_start'=>'شروع شیفت','cutoff'=>'پایان شیفت','weekend'=>'روزهای تعطیل هفتگی (۰ یکشنبه تا ۶ شنبه)'] as $key=>$label)echo '<label>'.esc_html($label).' <input name="'.esc_attr($key).'" value="'.esc_attr($key==='weekend'?implode(',',$p[$key]):$p[$key]).'"></label>';
  echo '<fieldset class="hmx-weekly-editor"><legend>شیفت هر روز هفته</legend><p>انتخاب «پیش‌فرض» از ساعات عمومی استفاده می‌کند. تعطیلی هفتگی از فیلد روزهای تعطیل پیروی می‌کند.</p>';
  foreach(['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'] as $day=>$name){$pair=$p['weekly_shifts'][$day]??[$p['work_start'],$p['cutoff']];echo '<label>'.esc_html($name).' <select name="weekly_mode['.$day.']"><option value="default">پیش‌فرض</option><option value="custom" '.(isset($p['weekly_shifts'][$day])?'selected':'').'>شیفت اختصاصی</option></select><input type="time" name="weekly_start['.$day.']" value="'.esc_attr($pair[0]).'" aria-label="شروع '.esc_attr($name).'"><input type="time" name="weekly_end['.$day.']" value="'.esc_attr($pair[1]).'" aria-label="پایان '.esc_attr($name).'"></label>';}
  echo '</fieldset>';
  foreach(['breaks'=>'بازه‌های استراحت','date_shifts'=>'شیفت استثنایی تاریخ'] as $key=>$title){echo '<fieldset class="hmx-interval-editor" data-kind="'.esc_attr($key).'"><legend>'.esc_html($title).'</legend>'; $rows=$p[$key];if(!$rows)$rows=$key==='breaks'?[['','']]:[''=>['','']];$row=0;foreach($rows as $date=>$pair){echo '<div class="hmx-interval-row">';if($key==='date_shifts')echo '<label>تاریخ میلادی <input type="date" name="date_shifts_date['.$row.']" value="'.esc_attr($date).'"></label><label><input type="checkbox" name="date_shifts_closed['.$row.']" '.($pair===[]?'checked':'').'>بسته</label>';echo '<label>شروع <input type="time" name="'.$key.'_start['.$row.']" value="'.esc_attr($pair[0]??'').'"></label><label>پایان <input type="time" name="'.$key.'_end['.$row.']" value="'.esc_attr($pair[1]??'').'"></label><button type="button" class="button hmx-remove-interval">حذف بازه</button></div>';$row++;}echo '<button type="button" class="button hmx-add-interval">افزودن بازه</button></fieldset>';}
  foreach(['holidays'=>'تعطیلات؛ هر سطر تاریخ میلادی','blackout_dates'=>'توقف پذیرش؛ هر سطر تاریخ میلادی'] as $key=>$label){$lines=[];foreach($p[$key] as $index=>$pair)$lines[]=in_array($key,['holidays','blackout_dates'],true)?$pair:($key==='breaks'?implode('|',$pair):$index.'|'.($pair===[]?'closed':implode('-',$pair)));echo '<label>'.esc_html($label).'<textarea name="'.esc_attr($key).'" rows="3" dir="ltr">'.esc_textarea(implode("\n",$lines)).'</textarea></label>';}
  echo '<details><summary>تنظیم پیشرفته اختیاری</summary><p>تنها در صورت نیاز وارد کنید؛ در غیر این صورت فیلدهای بالا ذخیره می‌شوند.</p><textarea name="policy_json" rows="8" dir="ltr" aria-label="سیاست پیشرفته"></textarea></details>';
 }
 private static function form(int $id,array $s,string $command,string $label,bool $open=false,bool $note=false,string $incident='',string $field=''): void {Support::form('hm_mahex_v34_policy');foreach(['order_id'=>$id,'revision'=>$s['revision']??0,'command'=>$command,'incident_id'=>$incident] as $k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';if($open){echo '<select name="type" aria-label="نوع استثنا">';foreach(self::types() as $k=>$v)echo '<option value="'.esc_attr($k).'">'.esc_html($v).'</option>';echo '</select><select name="severity" aria-label="شدت">';foreach(['low'=>'کم','medium'=>'متوسط','high'=>'زیاد','critical'=>'بحرانی'] as $k=>$v)echo '<option value="'.esc_attr($k).'">'.esc_html($v).'</option>';echo '</select>';}$note=$note||$open;if($note)echo '<input name="note" maxlength="1000" placeholder="دلیل یا نتیجه" required>';if($field)echo '<input type="'.(in_array($field,['deadline','due_at'],true)?'datetime-local':'number').'" min="'.(in_array($field,['deadline','due_at'],true)?'':'0').'" name="'.esc_attr($field).'" aria-label="'.esc_attr($field).'" required>';echo '<button class="button">'.esc_html($label).'</button></form>';}
}
